    private String IP;
    private String Port;
    private String URL_FTTH_Maintenance;
    private String URL_installation;
    private String URL_DATA_Maintenance;
    private ArrayList<XML> xmls_installation = new ArrayList<XML>();
    private ArrayList<XML> xmls_DATA_Maintenance = new ArrayList<XML>();
    private ArrayList<XML> xmls_FTTH_Maintenance = new ArrayList<XML>();
    public Create(String IP, String Port) throws XPathExpressionException, ParserConfigurationException, IOException, TransformerException, SAXException {
        this.IP=IP;
        this.Port=Port;
        this.URL_FTTH_Maintenance="http://"+this.IP+":"+this.Port+"/FCCWFMInteg-FCCWFMInteg-context-root/FCCWFMIntegPort";
        this.URL_installation = "http://"+this.IP+":"+this.Port+"/HiveAPIs/resources/hivews/CreateOrder";
        this.URL_DATA_Maintenance="http://"+this.IP+":"+this.Port+"/FCCHiveWS/WSPort";
        XML AVReSplitReserve_body = new XML (this.AVReSplitReserve_body);
        xmls_installation.add(AVReSplitReserve_body);
        XML ADSL_Un_Splitting = new XML (this.ADSL_Un_Splitting);
        xmls_installation.add(ADSL_Un_Splitting);
        XML Data_Down = new XML (this.Data_Down);
        xmls_DATA_Maintenance.add(Data_Down);
        XML Physical_Instability = new XML (this.Physical_Instability);
        xmls_DATA_Maintenance.add(Physical_Instability);
        XML FTTHNewSubVS = new XML (this.FTTHNewSubVS);
        xmls_installation.add(FTTHNewSubVS);
        XML FTTHMigrationSurvey = new XML (this.FTTHMigrationSurvey);
        xmls_installation.add(FTTHMigrationSurvey);
        XML FTTHDataVoiceDown = new XML (this.FTTHDataVoiceDown);
        xmls_FTTH_Maintenance.add(FTTHDataVoiceDown);
        XML FTTHWrongCardPort = new XML (this.FTTHWrongCardPort);
        xmls_FTTH_Maintenance.add(FTTHWrongCardPort);
    }
    public ArrayList<String> genrate_work_orders ( int number_of_work_orders) throws Exception {
        ArrayList <String> work_orders = new ArrayList<String>();
        int number_of_types = xmls_FTTH_Maintenance.size()+xmls_installation.size()+xmls_DATA_Maintenance.size();
        int[] ordersPerType = distribute_orders (number_of_work_orders,number_of_types);
        for(int i = 0; i<xmls_FTTH_Maintenance.size();i++)
        {
            for(int j=0; j<ordersPerType[i];j++)
            {
                work_orders.add(xmls_FTTH_Maintenance.get(i).send_creation_request_Maintenance
                        (xmls_FTTH_Maintenance.get(i).update_complain_number(),this.URL_FTTH_Maintenance));
            }
        }
        for(int i = 0; i<xmls_DATA_Maintenance.size();i++)
        {
            for(int j=0; j<ordersPerType[i];j++)
            {
                work_orders.add(xmls_DATA_Maintenance.get(i).send_creation_request_Maintenance
                        (xmls_DATA_Maintenance.get(i).update_complain_number(),this.URL_DATA_Maintenance));
            }
        }
        for(int i = 0; i<xmls_installation.size();i++)
        {
            for(int j=0; j<ordersPerType[i];j++)
            {
                work_orders.add(xmls_installation.get(i).send_creation_request_installation
                        (xmls_installation.get(i).randomize_OM_Order_ID(),this.URL_installation));
            }
        }
        return work_orders;
    }
    public int[] distribute_orders(int number_of_orders, int number_of_types) {
        int[] ordersPerType = new int[number_of_types];

        int baseOrders = number_of_orders / number_of_types;
        int remainder = number_of_orders % number_of_types;

        for (int i = 0; i < number_of_types; i++) {
            ordersPerType[i] = baseOrders + (i < remainder ? 1 : 0);
        }

        return ordersPerType;
    }
